original_prompt:
{
  "research_config": {
    "topic": "Logistics-Oriented and Car-Free Camping Planning Analysis",
    "target_persona": {
      "age_group": "${age_group:30-35}",
      "group_size": "${group_size:4}",
      "travel_mode": "Intermodal Transportation (Public Transit + Hiking/Walking Only)"
    },
    "output_lang": "${lang:English}"
  },
  "context": {
    "origin": "${origin:Ankara Yenimahalle}",
    "destination_region": "${destination:Nallihan}",
    "specific_date": "${date:March 14, 2026}",
    "priorities": [
      "Logistical feasibility",
      "Safety",
      "Nature immersion",
      "Minimalism/Ultralight approach"
    ]
  },
  "knowledge_base_requirements": {
    "transport_analysis": [
      "Main artery bus/train lines and specific stop locations",
      "First/Last Mile connectivity (Local shuttles, taxi availability, or trekking distance from the final stop)",
      "Weekend frequency and ticketing/payment methods (e.g., local transit cards vs. cash)"
    ],
    "site_selection_criteria": [
      "Accessibility: Max 5km hiking distance from public transit drop-off points",
      "Legality: Officially designated campsites or safe, legal wild camping zones",
      "Resource Availability: Proximity to water sources and basic necessities (WC/Market)"
    ]
  },
  "goal": {
    "primary_objective": "To create a sustainable, comfortable, and safe camping plan without a private vehicle.",
    "specific_research_tasks": [
      "Identify 3 distinct campsite typologies (e.g., lakeside, forest, high altitude) in the region.",
      "Curate a gear and meal list considering a strict backpack weight limit (max 15-18kg).",
      "Calculate distances to the nearest settlement and medical facilities for emergency protocols.",
      "Construct a precise timeline for a Saturday morning departure and Sunday evening return."
    ]
  },
  "output_structure": {
    "format": "Strategic Research Report",
    "sections": [
      "1. Transportation & Logistics Matrix",
      "2. Campsite Options (with Pros/Cons Analysis)",
      "3. Gear & Meal Planning (Ultralight & Practical)",
      "4. Step-by-Step Weekend Timeline (Chronological)",
      "5. Safety Protocols & Local Insider Tips"
    ],
    "tone": "Analytical, instructional, safe and encouraging"
  }
}

vi_prompt:
{
  "research_config": {
    "topic": "Phân tích kế hoạch cắm trại theo hướng hậu cần và không sử dụng xe ô tô cá nhân",
    "target_persona": {
      "age_group": "${age_group:30-35}",
      "group_size": "${group_size:4}",
      "travel_mode": "Giao thông đa phương thức (Chỉ sử dụng phương tiện công cộng + Đi bộ đường dài/Trekking)"
    },
    "output_lang": "${lang:English}"
  },
  "context": {
    "origin": "${origin:Ankara Yenimahalle}",
    "destination_region": "${destination:Nallihan}",
    "specific_date": "${date:March 14, 2026}",
    "priorities": [
      "Tính khả thi về mặt hậu cần",
      "Độ an toàn",
      "Hòa mình vào thiên nhiên",
      "Tiếp cận theo hướng tối giản / Siêu nhẹ (Ultralight)"
    ]
  },
  "knowledge_base_requirements": {
    "transport_analysis": [
      "Các tuyến xe buýt/tàu hỏa huyết mạch chính và vị trí các điểm dừng cụ thể",
      "Kết nối chặng đầu/chặng cuối (Xe trung chuyển địa phương, taxi hoặc quãng đường trekking từ điểm dừng cuối cùng)",
      "Tần suất hoạt động dịp cuối tuần và phương thức bán vé/thanh toán (vd: thẻ giao thông địa phương so với tiền mặt)"
    ],
    "site_selection_criteria": [
      "Khả năng tiếp cận: Đi bộ tối đa 5km từ các điểm dừng của phương tiện công cộng",
      "Tính hợp pháp: Các khu cắm trại được chỉ định chính thức hoặc khu cắm trại hoang dã an toàn, được phép",
      "Mức độ sẵn có của tài nguyên: Gần nguồn nước tự nhiên và các nhu yếu phẩm cơ bản (nhà vệ sinh/cửa hàng tạp hóa)"
    ]
  },
  "goal": {
    "primary_objective": "Xây dựng một kế hoạch cắm trại bền vững, thoải mái và an toàn mà không cần phương tiện cá nhân.",
    "specific_research_tasks": [
      "Xác định 3 loại hình địa điểm cắm trại khác biệt (vd: ven hồ, trong rừng, trên núi cao) trong khu vực.",
      "Lên danh sách trang thiết bị và thực phẩm tuân thủ nghiêm ngặt giới hạn trọng lượng balo (tối đa 15-18kg).",
      "Tính toán khoảng cách đến khu dân cư và cơ sở y tế gần nhất để lập quy trình ứng phó khẩn cấp.",
      "Xây dựng mốc thời gian biểu chi tiết khởi hành vào sáng thứ Bảy và trở về vào tối Chủ Nhật."
    ]
  },
  "output_structure": {
    "format": "Báo cáo nghiên cứu chiến lược",
    "sections": [
      "1. Ma trận Giao thông & Hậu cần",
      "2. Các phương án địa điểm cắm trại (kèm phân tích ưu/nhược điểm)",
      "3. Kế hoạch Trang bị & Bữa ăn (Siêu nhẹ & Thực tế)",
      "4. Lịch trình chi tiết từng bước cuối tuần (Theo trình tự thời gian)",
      "5. Quy chuẩn an toàn & Mẹo thực địa từ người dân bản xứ"
    ],
    "tone": "Phân tích, mang tính chỉ dẫn, an toàn và khích lệ tinh thần"
  }
}
